def parse_ticket(data):
    if "amount" not in data:
        return {"ok": False, "error": "MISSING_AMOUNT"}
    amount = data["amount"]
    if type(amount) is not int or amount < 0:
        return {"ok": False, "error": "INVALID_AMOUNT"}
    return {"ok": True, "amount": amount}
